import { setTimeout as delay } from "node:timers/promises";
import {
  TuituiBotClient,
  type TuituiEventBody,
} from "@qihoo/tuitui-bot-sdk";
import { loadSampleConfig } from "./config.js";

const config = loadSampleConfig();
const client = new TuituiBotClient(config.appId, config.appSecret);
const reportSubagent = process.argv.includes("--subagent");

client.event.subscribe({
  async onConnected() {
    const bot = await client.property.info();
    console.log(
      `机器人 \`${bot.name}\` 等待收消息。请私聊此机器人，或在群聊、团队帖子中 @该机器人`,
    );
  },
  onEvent(body) {
    if (body.event === client.event.SINGLE_CHAT) {
      void reportAgentEvents(body);
    } else if (body.event === client.event.GROUP_CHAT) {
      if (body.data?.at_me === true) void reportAgentEvents(body);
    } else if (body.event === client.event.TEAMS_POST_CREATE) {
      if (body.data?.at_me === true) void reportAgentEvents(body);
    }
  },
  onError(error) {
    console.error(error);
  },
});

async function reportAgentEvents(
  message: TuituiEventBody,
): Promise<void> {
  const ctx = client.agent.contextFromMessage(message);

  console.log(`收到 ${message.user_name} 的消息`);

  client.agent.report.message_received(ctx);

  client.agent.report.llm_input(ctx, { model: "sample-model", prompt: "查询北京天气" });
  await delay(2_000);

  client.agent.report.llm_output(
    ctx,
    {
      assistantTexts: [],
      thinking: "用户想要查询北京天气，我可以使用 weather 工具来查询",
      usage: { input: 10, output: 5, cacheRead: 0, total: 15 },
    },
  );
  await delay(1_000);

  const toolName = "weather";
  // 实际使用时应传入模型输出的 toolCallId，同一次工具调用的前后事件必须成对复用。
  const toolCallId = "abc1234567890";
  client.agent.report.before_tool_call(ctx, { toolCallId, toolName, params: { city: "北京" } });
  await delay(1_000);

  client.agent.report.after_tool_call(ctx, { toolCallId, toolName, result: "晴，气温 26 度" });

  if (reportSubagent) {
    const subagentContext = client.agent.buildSubagentContext({
      parentContext: ctx,
    });
    client.agent.report.subagent_spawned(
      subagentContext,
      { agentId: "Explore", label: "补充检查工具结果" },
    );
    client.agent.report.llm_input(
      subagentContext,
      { model: "sample-model", prompt: "复核主 Agent 的工具结果" },
    );
    client.agent.report.llm_output(
      subagentContext,
      {
        assistantTexts: ["子 Agent 复核完成"],
        thinking: "确认工具结果符合预期",
        usage: { input: 6, output: 3, cacheRead: 0, total: 9 },
      },
    );
    // 实际使用时应传入子 Agent 模型输出的 toolCallId，并在前后事件中成对复用。
    const subagentToolCallId = "def1234567890";
    client.agent.report.before_tool_call(
      subagentContext,
      { toolCallId: subagentToolCallId, toolName: "sample_verify", params: { result: "晴，气温 26 度" } },
    );
    client.agent.report.after_tool_call(
      subagentContext,
      { toolCallId: subagentToolCallId, toolName: "sample_verify", result: { verified: true } },
    );
    client.agent.report.subagent_ended(subagentContext, { outcome: "ok" });
  }

  client.agent.report.agent_end(ctx);

  console.log("Agent 执行中间步骤已全部加入上报队列");
}
